import java.util.Scanner;

abstract class RegraPreco {
    abstract int calcular(int preco);
}

class RegraNormal extends RegraPreco {
    @Override
    int calcular(int preco) {
        return preco;
    }
}

class RegraDesconto extends RegraPreco {
    @Override
    int calcular(int preco) {
        return preco * 90 / 100;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String tipo = scanner.next();
        int preco = scanner.nextInt();
        RegraPreco regra;
        if (tipo.equals("D")) {
            regra = new RegraDesconto();
        } else {
            regra = new RegraNormal();
        }
        System.out.println(regra.calcular(preco));
    }
}
